using Alterverse.AI;using Alterverse.Characters;using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.Combat
{
[RequireComponent(typeof(Health))]public sealed class LaneTower:MonoBehaviour
{
[SerializeField]private float attackRange=5.25f,attackDamage=18f,attackCooldown=1.2f;private readonly Collider[] hitBuffer=new Collider[32];private Health health;private int team;private float nextAttackTime;public int Team=>team;private void Awake()=>health=GetComponent<Health>();public void Initialize(int teamId)=>team=teamId;
private void Update(){if(Time.timeScale<=0f||health==null||health.IsDead)return;Health target=FindEnemyTarget();if(target==null)return;DimensionTowerShell shell=GetComponent<DimensionTowerShell>();if(shell!=null)shell.AimAt(target.transform.position);if(Time.time<nextAttackTime)return;if(shell!=null)shell.Fire();nextAttackTime=Time.time+attackCooldown;target.TakeDamage(attackDamage,gameObject);SpawnShot(target.transform.position);}
private Health FindEnemyTarget(){int count=Physics.OverlapSphereNonAlloc(transform.position,attackRange,hitBuffer,~0,QueryTriggerInteraction.Ignore);Health hero=null,minion=null;float heroSqr=float.MaxValue,minionSqr=float.MaxValue;for(int i=0;i<count;i++){Collider hit=hitBuffer[i];if(hit==null)continue;Health candidate=hit.GetComponentInParent<Health>();if(candidate==null||candidate==health||candidate.IsDead)continue;TeamMember member=candidate.GetComponent<TeamMember>();if(member!=null&&(member.GetComponent<HeroRespawn>()!=null||member.GetComponent<MobaBotRespawn>()!=null)){if(member.Team==team)continue;float sqr=(candidate.transform.position-transform.position).sqrMagnitude;if(sqr<heroSqr){heroSqr=sqr;hero=candidate;}continue;}LaneMinion laneMinion=candidate.GetComponent<LaneMinion>();if(laneMinion==null||laneMinion.Team==team)continue;float minionDistance=(candidate.transform.position-transform.position).sqrMagnitude;if(minionDistance<minionSqr){minionSqr=minionDistance;minion=candidate;}}return hero!=null?hero:minion;}
private void SpawnShot(Vector3 target){Color c=team==0?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy;DimensionTowerShell shell=GetComponent<DimensionTowerShell>();Vector3 origin=shell!=null?shell.MuzzlePosition:transform.position+Vector3.up*1.7f,direction=target-origin;float distance=direction.magnitude;if(distance<.01f)return;GameObject beam=GameObject.CreatePrimitive(PrimitiveType.Cube);beam.name="DF_TowerShot";beam.transform.position=origin+direction*.5f;beam.transform.rotation=Quaternion.LookRotation(direction);beam.transform.localScale=new Vector3(.11f,.11f,distance);Collider col=beam.GetComponent<Collider>();if(col!=null)col.enabled=false;Renderer r=beam.GetComponent<Renderer>();if(r!=null)r.material.color=c;PrototypeVfx.Ring(target,c,.65f,.18f);Destroy(beam,.1f);}
}
}
